ruleContent.content:
#chaptercontent@class.part@html
<js>
if (src.match(/您的VIP会员已过期/)) {
    java.toast("❗❗❗【重新注册一下，刷新试试】👻");
} else {
    // 获取页面中的特定元素
    var list = java.getElements("#chaptercontent@class.part");

    // 检查是否获取到元素
    if (!list || list.length === 0) {
        java.toast("⚠️ 未找到章节内容，请检查选择器是否正确！");
        result = "未找到章节内容";
    } else {
        list.sort((a, b) => {
            const numA = parseInt(a.attr("id").match(/\d+$/), 10) || 0;
            const numB = parseInt(b.attr("id").match(/\d+$/), 10) || 0;
            return numA - numB;
        });

        // 将排序后的元素内容拼接成字符串
        result = Array.from(list).map(item => item.text()).join("\n");
    }
}
result;
</js>

